  [286082] = { "Ti insegna a creare un Purple Rocket Cluster.", 0x2600308b, "u" },
  [286083] = { "Ti insegna a creare un ⟦White Rocket Cluster=Fascio di Razzi Bianchi⟧.", 0x197e2e6a, "u" },
  [286084] = { "Ti insegna a creare un ⟦Yellow Rocket Cluster=Fascio di Razzi Gialli⟧.", 0x71dff3b1, "u" },
