  [286087] = { "Ti insegna a creare un Large Yellow Rocket Cluster.", 0x1c57a422, "u" },
  [286152] = { { "Rigenera $N1 salute in $D1. Devi sederti per mangiare. Se mangi per almeno $D2 diventi Ben Nutrito e guadagni $N4 Armatura per $D3. Inoltre, l'esperienza ottenuta dalle uccisioni aumenta del $N6%.", "Rigenera $N1 salute in $D1. Devi sederti per mangiare. Se mangi per almeno $D2 diventi Ben Nutrito e guadagni $N4 Armatura per $D3. ", shape = { "6/3", "5/3" } }, 0xa37508da, "u" },
  [286153] = { "Ti insegna a cucinare un Pesce Corazzato.", 0xc3253d40, "u" },
  [286176] = { "Motiva un membro della Guardia della Morte.", 0x664cd0c8, "u" },
  [286263] = { "Che la ⟦Holy Light=Luce Sacra⟧ ci protegga nella nostra spedizione verso il gelido nord.", 0xeee6c8a9, "u" },
  [286264] = { "Vorrei proprio che voi maghi tiraste fuori la testa dai vostri... libri.", 0x2fdc6df9, "u" },
  [286265] = { "Possano le mie sorelle realizzare appieno il loro potenziale, e il nome Windrunner essere conosciuto grazie alle loro gesta.", 0x38e334d2, "u" },
  [286266] = { "Concedimi la forza di accettare le cose che non posso cambiare, il coraggio di cambiare quelle che posso e la saggezza di conoscerne la differenza.", 0xa430a556, "u" },
  [286267] = { "Oh, perché non mi noti? Abbendis, ti seguirei ovunque. Vorrei tanto che mi notassi...", 0x54ac42ab, "u" },
  [286268] = { "Prego che, quando verrà il momento, io abbia la forza di respingere le forze al di là del portale.", 0x06550e08, "u" },
  [286270] = { "Ma come funziona questa fontana? Chissà se potrei costruirne una.", 0x9e07f333, "u" },
  [286271] = { "Turalyon e Alleria, ovunque voi siate, spero che stiate bene.", 0xc8d073fa, "u" },
  [286272] = { "Che mio figlio Arthas agisca sempre nell'interesse del suo popolo.", 0xdd75c0be, "u" },
  [286273] = { "Dov'è Illidan?", 0xf4f231cf, "u" },
  [286274] = { "<Senti risuonare tre note nella tua testa, la terza appena udibile sotto il frastuono delle altre.>", 0x9917df10, "u" },
  [286275] = { "Spero che mio padre e i miei fratelli mi sopravvivano. Non sarei un granché come re.", 0x4da49bfd, "u" },
  [286279] = { "Vorrei tanto crescere: mi sembra di avere $N1 anni da una vita.", 0xb991d825, "u" },
  [286280] = { "Il giovane Arthas deve imparare la pazienza per temperare il suo potere. Pregherò perché un giorno impari a guidare con premura anziché con la forza.", 0xbb389a87, "u" },
  [286281] = { "Ho già un regno in prospettiva, una terra da governare. Cosa chiedere? Forse un pasticcino gelato...", 0xd1122935, "u" },
  [286283] = { "Un giorno vorrei ritirarmi in una mia piccola tenuta ordinata, con un branco di cani a farmi compagnia.", 0xd20396c6, "u" },
  [286284] = { "Brann Barbabronzea è stato qui.", 0x851089b6, "u" },
  [286287] = { "A volte... vorrei che arrivasse qualcuno a darmi un lungo, grande abbraccio.", 0xc021960f, "u" },
  [286288] = { "Arthas, amore mio, ti prego, torna da me.", 0x75d29e0f, "u" },
  [286290] = { "Ascolta, piccola fontana dei desideri. Mi darai tutto il tuo potere, se sai cosa ti conviene.", 0xdae8a1fb, "u" },
  [286291] = { "Spero che io e le mie sorelle cresceremo e ci sposeremo insieme. Questa moneta sembra molto antica.", 0x11a6603a, "u" },
  [286292] = { "Desidero che il mio caro Taelan diventi abbastanza forte da difendere le persone a cui tiene.", 0x5c5303f2, "u" },
  [286293] = { "Vorrei sapere come sei sopravvissuta alla mia ira, piccola fontana.", 0x3846ac8d, "u" },
  [286294] = { "Spiegami i miei sogni, piccola fontana. Perché devo sempre guardare i miei simili dall'alto e muoverli come pedine?", 0x275f4627, "u" },
  [286298] = { "A quanto pare i miei giorni da postino come secondo lavoro stanno per finire.", 0x7cf94019, "u" },
  [286299] = { "Grom, riposa in pace, vecchio amico.", 0xb8d72ae3, "u" },
  [286300] = { "Non ha senso. Perché sto gettando una moneta in una fontana?", 0xa022f596, "u" },
  [286302] = { "Quante monete brillano nella vasca. Forse nessuno se ne accorgerà se ne prendo solo una.", 0xdc487275, "u" },
  [286304] = { "Vorrei avere il compito di quel mio cugino, che non deve far altro che trascinarsi dietro legna senza pensieri...", 0xf77f1f2f, "u" },
  [286306] = { "Vorrei che il capitano Sanders si sbrigasse con il mio carico di vino.", 0x38184765, "u" },
  [286307] = { "Desidero felicità e accettazione per mia figlia. Si sente così fuori posto qui...", 0x2dd81161, "u" },
  [286308] = { "Posso avere una sella più comoda? Mi fa male il posteriore.", 0xc0d11bc5, "u" },
  [286309] = { "Spero che un troll muoia, proprio... ORA.", 0x5c88ac6d, "u" },
  [286310] = { "Fare il Ladro è un lavoro duro. Un giorno spero di seguire l'unica vera passione della mia vita...", 0xb0b1aeae, "u" },
  [286311] = { "Spero di finire prima o poi in un altro libro.", 0x1e072bac, "u" },
  [286312] = { "Vorrei riavere mio padre...", 0xb0bf1a4d, "u" },
  [286313] = { "Vorrei aver tenuto quella moneta...", 0xfbe57df5, "u" },
  [286314] = { "Vorrei che la gente la smettesse di far cadere i miei giocattoli dallo scaffale.", 0xedc3d7a9, "u" },
  [286315] = { "Avrei potuto usare questo rame per qualcosa di utile. Magari qualcosa con uno spago e una macchina.", 0x73a4a2cf, "u" },
  [286316] = { "Qui non è nemmeno magico.", 0x106f5f9e, "u" },
  [286317] = { "Come fa una taverna a rimanere senza birra!", 0x125e62d9, "u" },
  [286318] = { "Mi mancano la mia spada e il mio scudo. Senza la mia spada e il mio scudo mi sento come senza vestiti.", 0x1dfe3ecb, "u" },
  [286327] = { "Ecco a te, Nozdormu. Cosa dovevo fare dopo?", 0x82b4980c, "u" },
  [286328] = { "Come dimostro che ci hanno copiati con questa fontana?", 0xfb150113, "u" },
  [286405] = { { "Non m'ama...", "M'ama...", shape = { "0/0", "0/0" }, key = { "9d5894e7a9039387", "5d2047f07372cb7f" } }, 0xf327873f, "u" },
  [286537] = { "Colpisce i nemici vicini con un pestone tonante, infliggendo $N1 danni da natura.", 0x96e923c5, "u" },
  [286541] = { "Rigenera $N1 mana in $D1. Devi sederti per bere.", 0xf502561a, "u" },
  [286556] = { "Rallenta i nemici vicini del $N1% per $D1, valore che sale al $N3% nelle zone desertiche.", 0x124abd59, "u" },
  [286568] = { "Preso da una iena che divorava qualsiasi cosa, o chiunque.", 0x2a7b9883, "u" },
  [286648] = { "Gettalo in un'Unstable Mana Rift.", 0xee05b862, "u" },
  [286732] = { "Getta la moneta fortunata in acqua per aumentare la Pesca di $N1 per $D1.", 0x7f1bac15, "u" },
  [286734] = { "Aumenta la velocità degli attacchi a distanza del $N1%.", 0x3009bf39, "u" },
  [286982] = { "Infligge $N1 danni da natura ogni volta che blocchi un attacco. I danni raddoppiano nelle paludi.", 0x565638e9, "u" },
  [286986] = { "A volte vai proprio così di fretta.", 0x42db3113, "u" },
})
